import subprocess, os, tempfile
EXE="/workspace/executable"
def fresh(files=False):
    td=tempfile.mkdtemp(); home=os.path.join(td,"home"); os.makedirs(home); repo=os.path.join(td,"repo"); os.makedirs(repo)
    subprocess.run(["git","-C",repo,"init","-q"]); subprocess.run(["git","-C",repo,"config","user.email","t@t.com"]); subprocess.run(["git","-C",repo,"config","user.name","T"])
    return td,home,repo
def run(home,repo,*a,env=None):
    e=dict(os.environ); e.update(HOME=home,DSTASK_GIT_REPO=repo); 
    if env: e.update(env)
    p=subprocess.run([EXE]+list(a),capture_output=True,text=True,env=e)
    print(a, p.returncode, repr(p.stdout), repr(p.stderr))
    return p
td,home,repo=fresh()
run(home,repo,"add","one")
print(subprocess.run(["find",repo,"-type","f"],capture_output=True,text=True).stdout)
# decode state files
import pathlib
for p in pathlib.Path(repo).rglob("*"):
    if p.is_file() and 'dstask' in str(p):
        print(p, p.read_bytes()[:200])
run(home,repo,"context","+work")
print(subprocess.run(["find",repo,"-type","f","-not","-path","*/.git/objects/*"],capture_output=True,text=True).stdout)
for root,dirs,files in os.walk(repo):
    if '.git' in root and 'objects' not in root:
        for f in files:
            pp=os.path.join(root,f)
            if 'dstask' in pp or 'context' in pp:
                print(pp, open(pp,'rb').read()[:300])
# context file may be at root?
for f in os.listdir(repo): print(f)
PY
"}

