{"command":"cat > dstask/util.go <<'EOF'
package dstask

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

func ExitError(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintf(os.Stderr, "\x1b[31m%s\x1b[0m\n", msg)
	os.Exit(1)
}

func exitErrorNoNewline(format string, args ...interface{}) {
	// kept for parity with helpers that format their own trailing newline
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintf(os.Stderr, "\x1b[31m%s\x1b[0m\n", msg)
	os.Exit(1)
}

var _ = exitErrorNoNewline

func IsInteractive() bool {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return true
	}
	return isTerminalFD(int(os.Stdout.Fd()))
}

func isRealTerminal() bool {
	return isTerminalFD(int(os.Stdout.Fd()))
}

func isTerminalFD(fd int) bool {
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5401), uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

type winSize struct {
	Rows uint16
	Cols uint16
	X    uint16
	Y    uint16
}

func terminalSize() (int, int) {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return 80, 24
	}
	var ws winSize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdout.Fd()), uintptr(0x5413), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0
	}
	return int(ws.Cols), int(ws.Rows)
}

func ConfirmOrAbort(prompt string) {
	fmt.Fprintf(os.Stderr, "%s [y/n] ", prompt)
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	if err != nil {
		panic(err)
	}
	ans := strings.TrimSpace(strings.ToLower(line))
	if ans != "y" && ans != "yes" {
		ExitError("Aborted.")
	}
}

var _ = io.EOF

func slugify(summary string) string {
	lower := strings.ToLower(summary)
	var b strings.Builder
	lastSpace := false
	for _, r := range lower {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			b.WriteRune(r)
			lastSpace = false
		} else if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
			if !lastSpace {
				b.WriteByte('-')
				lastSpace = true
			}
		} else {
			// punctuation and non-ascii letters are dropped entirely
		}
	}
	s := b.String()
	if len(s) > 21 {
		s = s[:21]
	}
	return s
}
EOF
cat > dstask/query.go <<'EOF'
package dstask

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      int
	Text          string
	IgnoreContext bool
	Note          string
}

var commandNames = map[string]bool{
	"next": true, "show-next": true, "add": true, "rm": true, "remove": true,
	"template": true, "log": true, "start": true, "note": true, "notes": true,
	"stop": true, "done": true, "resolve": true, "context": true, "modify": true,
	"edit": true, "undo": true, "sync": true, "open": true, "git": true,
	"show-projects": true, "show-tags": true, "show-active": true, "show-paused": true,
	"show-open": true, "show-resolved": true, "show-templates": true, "show-unorganised": true,
	"bash-completion": true, "fish-completion": true, "zsh-completion": true,
	"help": true, "version": true, "_completions": true,
}

func ParseQuery(args []string) (Query, error) {
	q := Query{
		IDs:          []int{},
		Tags:         []string{},
		AntiTags:     []string{},
		AntiProjects: []string{},
	}
	var textWords []string
	var noteWords []string
	inNotes := false
	cmdFound := false
	dueSeen := false

	for _, token := range args {
		if inNotes {
			noteWords = append(noteWords, token)
			continue
		}
		if token == "/" {
			inNotes = true
			continue
		}
		if !cmdFound {
			if commandNames[strings.ToLower(token)] {
				q.Cmd = strings.ToLower(token)
				cmdFound = true
				continue
			}
		}
		if token == "--" {
			q.IgnoreContext = true
			continue
		}
		if n, err := strconv.Atoi(token); err == nil {
			q.IDs = append(q.IDs, n)
			continue
		}
		lower := strings.ToLower(token)
		if strings.HasPrefix(lower, "due:") {
			if dueSeen {
				return q, fmt.Errorf("Query should only have one due date")
			}
			dueSeen = true
			dueStr := lower[len("due:"):]
			d, err := parseDueDate(dueStr)
			if err != nil {
				return q, err
			}
			q.Due = d
			continue
		}
		if strings.HasPrefix(lower, "template:") {
			n, err := strconv.Atoi(lower[len("template:"):])
			if err != nil {
				q.Template = 0
			} else {
				q.Template = n
			}
			continue
		}
		if strings.HasPrefix(lower, "-project:") {
			q.AntiProjects = append(q.AntiProjects, lower[len("-project:"):])
			continue
		}
		if strings.HasPrefix(lower, "project:") {
			if q.Project == "" {
				q.Project = lower[len("project:"):]
			} else {
				textWords = append(textWords, token)
			}
			continue
		}
		if token == "P0" || token == "P1" || token == "P2" || token == "P3" {
			if q.Priority == "" {
				q.Priority = token
			} else {
				textWords = append(textWords, token)
			}
			continue
		}
		if strings.HasPrefix(token, "+") && len(token) > 1 {
			q.Tags = append(q.Tags, lower[1:])
			continue
		}
		if strings.HasPrefix(token, "-") && len(token) > 1 {
			q.AntiTags = append(q.AntiTags, lower[1:])
			continue
		}
		textWords = append(textWords, token)
	}
	q.Text = strings.Join(textWords, " ")
	q.Note = strings.Join(noteWords, " ")
	if !cmdFound {
		q.Cmd = "next"
	}
	return q, nil
}

func (q Query) String() string {
	var parts []string
	for _, id := range q.IDs {
		parts = append(parts, strconv.Itoa(id))
	}
	for _, t := range q.Tags {
		parts = append(parts, "+"+t)
	}
	for _, t := range q.AntiTags {
		parts = append(parts, "-"+t)
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
	}
	for _, p := range q.AntiProjects {
		parts = append(parts, "-project:"+p)
	}
	if !q.Due.IsZero() {
		parts = append(parts, "due:"+q.Due.Format("2006-01-02"))
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
	}
	if q.Template != 0 {
		parts = append(parts, "template:"+strconv.Itoa(q.Template))
	}
	if q.Text != "" {
		parts = append(parts, "\""+q.Text+"\"")
	}
	return strings.Join(parts, " ")
}

// hasOperators reports whether the query carries any attribute / operator
// fields (everything except text, note, command and --).
func (q Query) hasOperators() bool {
	return len(q.IDs) > 0 || len(q.Tags) > 0 || len(q.AntiTags) > 0 || q.Project != "" ||
