			return fmt.Errorf("Could not apply q2, priority conflict")
		}
		q.Priority = q2.Priority
	}
	q.Tags = append(q.Tags, q2.Tags...)
	q.AntiTags = append(q.AntiTags, q2.AntiTags...)
	q.AntiProjects = append(q.AntiProjects, q2.AntiProjects...)
	return nil
}

func parseDueDate(s string) (time.Time, error) {
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	invalid := func() (time.Time, error) {
		return time.Time{}, fmt.Errorf("Invalid due date format: %s\nExpected format: YYYY-MM-DD, MM-DD or DD, relative date like 'next-monday', 'today', etc.", s)
	}
	switch s {
	case "today":
		return today, nil
	case "tomorrow":
		return today.AddDate(0, 0, 1), nil
	case "yesterday":
		return today.AddDate(0, 0, -1), nil
	}
	if t, err := time.Parse("2006-01-02", s); err == nil {
		return t, nil
	}
	if t, err := time.Parse("01-02", s); err == nil {
		return time.Date(now.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.UTC), nil
	}
	if t, err := time.Parse("2", s); err == nil {
		return time.Date(now.Year(), now.Month(), t.Day(), 0, 0, 0, 0, time.UTC), nil
	}
	weekdays := map[string]time.Weekday{
		"sunday": time.Sunday, "sun": time.Sunday,
		"monday": time.Monday, "mon": time.Monday,
		"tuesday": time.Tuesday, "tue": time.Tuesday, "tues": time.Tuesday,
		"wednesday": time.Wednesday, "wed": time.Wednesday,
		"thursday": time.Thursday, "thu": time.Thursday, "thur": time.Thursday, "thurs": time.Thursday,
		"friday": time.Friday, "fri": time.Friday,
		"saturday": time.Saturday, "sat": time.Saturday,
	}
	if wd, ok := weekdays[s]; ok {
		diff := (int(wd) - int(today.Weekday()) + 7) % 7
		return today.AddDate(0, 0, diff), nil
	}
	if strings.Contains(s, "-") {
		parts := strings.Split(s, "-")
		if len(parts) == 2 {
			if wd, ok := weekdays[parts[1]]; ok {
				signed := int(wd) - int(today.Weekday())
				switch parts[0] {
				case "next":
					return today.AddDate(0, 0, signed+7), nil
				case "this", "":
					if signed < 0 {
						signed += 7
					}
					return today.AddDate(0, 0, signed), nil
				default:
					return today.AddDate(0, 0, signed), nil
				}
			}
		}
	}
	return invalid()
}
