{"command":"cat > dstask/taskset.go <<'EOF'
package dstask

import (
	"crypto/rand"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

type TaskSet struct {
	RepoPath string
	Tasks    []*Task
	ids      IdsMap
}

func newUUID() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic(err)
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func LoadTaskSet(repo string) *TaskSet {
	ts := &TaskSet{RepoPath: repo, ids: IdsMap{}}
	loadGobFile(idsFilePath(repo), &ts.ids)
	if ts.ids == nil {
		ts.ids = IdsMap{}
	}
	for _, status := range loadStatusOrder {
		dir := filepath.Join(repo, status)
		entries, err := os.ReadDir(dir)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			ExitError("%s", err.Error())
		}
		for _, entry := range entries {
			name := entry.Name()
			task, err := loadTaskFile(dir, name, status)
			if err != nil {
				log.Printf("error loading task: %s", err.Error())
				continue
			}
			ts.Tasks = append(ts.Tasks, task)
		}
	}
	ts.assignIDs()
	return ts
}

func loadTaskFile(dir, name, status string) (*Task, error) {
	if len(name) != 40 {
		return nil, fmt.Errorf("filename does not encode UUID %s (wrong length)", name)
	}
	uuid := name[:36]
	if !isUUIDString(uuid) {
		return nil, fmt.Errorf("filename does not encode UUID %s", name)
	}
	data, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		return nil, fmt.Errorf("failed to read %s", name)
	}
	var task Task
	if err := yaml.Unmarshal(data, &task); err != nil {
		return nil, fmt.Errorf("failed to unmarshal %s", name)
	}
	task.Uuid = uuid
	task.Status = status
	task.origStatus = status
	task.Normalise()
	if err := validateLoad(&task); err != nil {
		return nil, err
	}
	return &task, nil
}

func (ts *TaskSet) assignIDs() {
	used := map[int]bool{}
	for _, task := range ts.Tasks {
		if task.Status == StatusResolved {
			task.ID = 0
			continue
		}
		if id, ok := ts.ids[task.Uuid]; ok && id != 0 && !used[id] {
			task.ID = id
		} else {
			id := 1
			for used[id] {
				id++
			}
			task.ID = id
		}
		used[task.ID] = true
	}
}

func (ts *TaskSet) nextID() int {
	used := map[int]bool{}
	for _, task := range ts.Tasks {
		if task.Status != StatusResolved && task.ID != 0 {
			used[task.ID] = true
		}
	}
	id := 1
	for used[id] {
		id++
	}
	return id
}

func (ts *TaskSet) AddTask(task *Task) {
	ts.Tasks = append(ts.Tasks, task)
	if task.Status != StatusResolved && task.ID == 0 {
		// compute excluding the new task itself (its ID is still 0)
		task.ID = ts.nextID()
	}
}

type taskFile struct {
	Summary      string    `yaml:"summary"`
	Notes        string    `yaml:"notes"`
	Tags         []string  `yaml:"tags"`
	Project      string    `yaml:"project"`
	Priority     string    `yaml:"priority"`
	DelegatedTo  string    `yaml:"delegatedto"`
	Subtasks     []SubTask `yaml:"subtasks"`
	Dependencies []string  `yaml:"dependencies"`
	Created      timeField `yaml:"created"`
	Resolved     timeField `yaml:"resolved"`
	Due          timeField `yaml:"due"`
}

// timeField is an alias so the shadow struct marshals identically.
type timeField = timeType

func (ts *TaskSet) taskPath(task *Task) string {
	return filepath.Join(ts.RepoPath, task.Status, task.Uuid+".yml")
}

func (ts *TaskSet) ensureDirs() {
	for _, status := range allStatusesForDirs {
		// errors are surfaced by the subsequent write where relevant
		_ = os.MkdirAll(filepath.Join(ts.RepoPath, status), 0700)
	}
}

func (ts *TaskSet) SaveTask(task *Task, msg string) {
	task.Normalise()
	if err := validateSave(task); err != nil {
		ExitError("%s", err.Error())
	}
	if task.Status == StatusResolved && task.Resolved.IsZero() {
		// resolved timestamp is supplied by ChangeStatus for the common
		// paths; this covers direct saves such as edits.
		task.Resolved = nowUTC()
	}
	if task.Status != StatusResolved && task.ID == 0 {
		task.ID = ts.nextID()
	}
	ts.ensureDirs()
	tf := taskFile{
		Summary:      task.Summary,
		Notes:        task.Notes,
		Tags:         task.Tags,
		Project:      task.Project,
		Priority:     task.Priority,
		DelegatedTo:  task.DelegatedTo,
		Subtasks:     task.Subtasks,
		Dependencies: task.Dependencies,
		Created:      task.Created,
		Resolved:     task.Resolved,
		Due:          task.Due,
	}
	data, err := yaml.Marshal(tf)
	if err != nil {
		ExitError("Failed to write task %s", task.String())
	}
	path := ts.taskPath(task)
	if err := os.WriteFile(path, data, 0600); err != nil {
		ExitError("Failed to write task %s", task.String())
	}
	if task.origStatus != "" && task.origStatus != task.Status {
		oldPath := filepath.Join(ts.RepoPath, task.origStatus, task.Uuid+".yml")
		if err := os.Remove(oldPath); err != nil {
			ExitError("Could not remove task %s: %s", oldPath, err.Error())
		}
	}
	ts.SaveIDs()
	fmt.Printf("\n%s\n", msg)
	gitCommit(ts.RepoPath, msg)
	if task.Status == StatusResolved {
		task.ID = 0
	}
	task.origStatus = task.Status
}

func (ts *TaskSet) SaveIDs() {
	ids := IdsMap{}
	for _, task := range ts.Tasks {
		if task.Status != StatusResolved {
			ids[task.Uuid] = task.ID
		}
	}
	saveGobFile(idsFilePath(ts.RepoPath), ids)
	ts.ids = ids
}

func (ts *TaskSet) GetOpenTask(id int) *Task {
	for _, task := range ts.Tasks {
		if task.ID == id && task.Status != StatusResolved {
			return task
		}
	}
	ExitError("no open task with ID %d exists", id)
	return nil
}

// snapshotOpenTasks builds an ID -> task map of currently open tasks so
// batch operations keep operating on the same task objects even if an
// earlier operation in the same invocation changes their status/ID.
func (ts *TaskSet) snapshotOpenTasks() map[int]*Task {
	m := map[int]*Task{}
	for _, task := range ts.Tasks {
		if task.Status != StatusResolved {
			if _, exists := m[task.ID]; !exists {
				m[task.ID] = task
			}
		}
