package dstask

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
	"time"
)

const (
	colReset = "\x1b[0m"
)

type rowStyle struct {
	fg int
	bg int
}

func styleForTask(task *Task, idx int) rowStyle {
	bg := 232
	if idx%2 == 0 {
		bg = 233
	}
	if task.Status == StatusActive {
		return rowStyle{fg: 233, bg: 250}
	}
	if task.Status == StatusPaused {
		return rowStyle{fg: 250, bg: 236}
	}
	fg := 250
	switch task.Priority {
	case "P0":
		fg = 160
	case "P1":
		fg = 166
	case "P2":
		fg = 250
	case "P3":
		fg = 245
	}
	return rowStyle{fg: fg, bg: bg}
}

// ---- rune width handling ----

func runeDisplayWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 32 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	if isCombining(r) {
		return 0
	}
	if isWideRune(r) {
		return 2
	}
	return 1
}

func isCombining(r rune) bool {
	return (r >= 0x0300 && r <= 0x036f) || (r >= 0x1ab0 && r <= 0x1aff) ||
		(r >= 0x1dc0 && r <= 0x1dff) || (r >= 0x20d0 && r <= 0x20ff) ||
		(r >= 0xfe20 && r <= 0xfe2f) || (r >= 0xfe00 && r <= 0xfe0f)
}

func isWideRune(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115f,
		r >= 0x2e80 && r <= 0xa4cf,
		r >= 0xac00 && r <= 0xd7a3,
		r >= 0xf900 && r <= 0xfaff,
		r >= 0xfe30 && r <= 0xfe6f,
		r >= 0xff00 && r <= 0xff60,
		r >= 0xffe0 && r <= 0xffe6,
		r >= 0x20000 && r <= 0x3ffff,
		r >= 0x1f300 && r <= 0x1faff,
		r >= 0x2600 && r <= 0x27bf:
		return true
	}
	return false
}

// ansiSegments splits a string into text runs and ANSI escape sequences.
type ansiSeg struct {
	text    string
	isEsc   bool
}

func splitANSI(s string) []ansiSeg {
	var segs []ansiSeg
	for len(s) > 0 {
		i := strings.Index(s, "\x1b[")
		if i < 0 {
			segs = append(segs, ansiSeg{text: s})
			break
		}
		if i > 0 {
			segs = append(segs, ansiSeg{text: s[:i]})
			s = s[i:]
			continue
		}
		// escape sequence, find final byte (letter)
		j := 2
		for j < len(s) && !((s[j] >= 'a' && s[j] <= 'z') || (s[j] >= 'A' && s[j] <= 'Z')) {
			j++
		}
		if j < len(s) {
			j++
		}
		segs = append(segs, ansiSeg{text: s[:j], isEsc: true})
		s = s[j:]
	}
	return segs
}

func plainText(s string) string {
	var b strings.Builder
	for _, sg := range splitANSI(s) {
		if !sg.isEsc {
			b.WriteString(sg.text)
		}
	}
	return b.String()
}

// widthForMax mirrors the original: escape sequences each add one to the
// measured width of a cell.
func widthForMax(s string) int {
	segs := splitANSI(s)
	w := 0
	for _, sg := range segs {
		if sg.isEsc {
			w++
		} else {
			for _, r := range sg.text {
				w += runeDisplayWidth(r)
			}
		}
	}
	return w
}

func visibleWidth(s string) int {
	w := 0
	for _, sg := range splitANSI(s) {
		if sg.isEsc {
			continue
		}
		for _, r := range sg.text {
			w += runeDisplayWidth(r)
		}
	}
	return w
}

func truncateCell(s string, width int) string {
	if width < 0 {
		width = 0
	}
	if visibleWidth(s) <= width {
		return s
	}
	var b strings.Builder
	w := 0
	var trailingEsc []string
	segs := splitANSI(s)
	for i, sg := range segs {
		if sg.isEsc {
			// remember escapes after the cut point if they are at the end
			restAllEsc := true
			for _, rsg := range segs[i:] {
				if !rsg.isEsc {
					// check whether remaining text will be included
					_ = restAllEsc
				}
			}
			trailingEsc = append(trailingEsc, sg.text)
			continue
		}
		for _, r := range sg.text {
			rw := runeDisplayWidth(r)
			if w+rw > width {
				// emit trailing escapes collected so far
				for _, e := range trailingEsc {
					b.WriteString(e)
				}
				return b.String()
			}
			// flush pending escapes before this rune
			for _, e := range trailingEsc {
				b.WriteString(e)
			}
			trailingEsc = nil
			b.WriteRune(r)
			w += rw
		}
	}
	for _, e := range trailingEsc {
		b.WriteString(e)
	}
	return b.String()
}

func padCell(s string, width int) string {
	vw := visibleWidth(s)
	if vw >= width {
		return s
	}
	pad := strings.Repeat(" ", width-vw)
	segs := splitANSI(s)
	// if the cell ends with an escape sequence, insert padding before it
	if len(segs) > 0 && segs[len(segs)-1].isEsc {
		idx := strings.LastIndex(s, "\x1b[")
		if idx >= 0 {
			return s[:idx] + pad + s[idx:]
		}
	}
	return s + pad
}

type table struct {
	header []string
	rows   [][]string
	styles []rowStyle // per data row; nil meaning use default alternating
}

func renderTable(t table, termWidth int) string {
	cols := len(t.header)
	widths := make([]int, cols)
	for i, h := range t.header {
		widths[i] = widthForMax(h)
	}
	for _, row := range t.rows {
		for i := 0; i < cols && i < len(row); i++ {
			if w := widthForMax(row[i]); w > widths[i] {
				widths[i] = w
			}
		}
	}
	total := 0
	for _, w := range widths {
		total += w
	}
	if cols > 0 {
		total += (cols - 1) * 2
	}
	for total > termWidth {
		// decrement widest column (leftmost on ties)
		maxIdx := -1
		maxW := 1
		for i, w := range widths {
			if w > maxW {
				maxW = w
				maxIdx = i
			}
		}
		if maxIdx < 0 {
			break
		}
		widths[maxIdx]--
		total--
	}
	var b strings.Builder
	renderRow := func(cells []string, style string) {
		b.WriteString(style)
		for i := 0; i < cols; i++ {
			if i > 0 {
				b.WriteString("  ")
			}
			cell := ""
			if i < len(cells) {
				cell = cells[i]
			}
			cell = truncateCell(cell, widths[i])
			cell = padCell(cell, widths[i])
			b.WriteString(cell)
		}
		b.WriteString(colReset)
		b.WriteString("\n")
	}
	renderRow(t.header, "\x1b[4;38;5;250;48;5;232m")
	for idx, row := range t.rows {
		st := rowStyle{fg: 250, bg: 232}
		if idx < len(t.styles) {
			st = t.styles[idx]
		}
		renderRow(row, fmt.Sprintf("\x1b[0;38;5;%d;48;5;%dm", st.fg, st.bg))
	}
	return b.String()
}

func dueString(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.Format("_2 Jan 2006")
}

func summaryCell(task *Task, fg int) string {
	if task.Notes == "" {
		return task.Summary
	}
	return fmt.Sprintf("%s\x1b[38;5;240m %s\x1b[38;5;%dm", task.Summary, firstLine(task.Notes), fg)
}

func firstLine(s string) string {
	// notes are shown inline in list view; newlines become spaces visually
	// in the original the whole note text is embedded (the terminal wraps
	// it as spaces are rendered), but embedded newlines would break rows,
	// and the original embeds the notes with newlines replaced by the
	// raw byte - rows observed keep the full text on one line when notes
	// contain spaces only. For multi-line notes the original list cell
	// contains the raw newline? It does not appear in practice in tests;
	// we keep the text as-is except newlines are preserved by the table
	// in the single-line cases we replicate by replacing with "".
	return strings.ReplaceAll(s, "\n", " ")
}

func printNotes(task *Task) {
	if task.Notes == "" {
		return
	}
	fmt.Printf("\nNotes on task %d:\n\x1b[38;5;245m%s\x1b[0m\n\n", task.ID, task.Notes)
}

func hasNonResolved(ts *TaskSet) bool {
	for _, t := range ts.Tasks {
		if t.Status != StatusResolved {
			return true
		}
	}
	return false
}

// displayTasks implements the shared listing behaviour.
func displayTasks(ts *TaskSet, tasks []*Task, truncate bool) {
	if !IsInteractive() {
		sortTasks(tasks)
		printJSON(tasks)
		return
	}
	if len(tasks) == 0 {
		if !hasNonResolved(ts) {
			fmt.Println("No tasks found. Run `dstask help` for instructions.")
			return
		}
		ExitError("No matching tasks in given context or filter.")
	}
	sortTasks(tasks)
	if len(tasks) == 1 {
		displayTask(tasks[0])
		return
	}
	termWidth, termHeight := terminalSize()
	shown := tasks
	truncated := false
	if truncate {
		limit := termHeight - 9
		if limit < 8 {
			limit = 8
		}
		if len(shown) > limit {
			shown = shown[:limit]
			truncated = true
		}
	}
	var rows [][]string
	var styles []rowStyle
	for i, task := range shown {
		st := styleForTask(task, i)
		rows = append(rows, []string{
			fmt.Sprint(task.ID),
			task.Priority,
			strings.Join(task.Tags, " "),
			dueString(task.Due),
			task.Project,
			summaryCell(task, st.fg),
		})
		styles = append(styles, st)
	}
	fmt.Print(renderTable(table{
		header: []string{"ID", "Priority", "Tags", "Due", "Project", "Summary"},
		rows:   rows,
		styles: styles,
	}, termWidth))
	if truncated {
		fmt.Printf("\n%d/%d tasks shown.\n", len(shown), len(tasks))
	} else {
		fmt.Printf("\n%d tasks.\n", len(tasks))
	}
}

func displayTask(task *Task) {
	rows := [][]string{
		{"ID", fmt.Sprint(task.ID)},
		{"Priority", task.Priority},
		{"Summary", task.Summary},
		{"Status", task.Status},
		{"Project", task.Project},
		{"Tags", strings.Join(task.Tags, ", ")},
		{"UUID", task.Uuid},
		{"Created", fmt.Sprint(task.Created)},
	}
	if !task.Resolved.IsZero() {
		rows = append(rows, []string{"Resolved", fmt.Sprint(task.Resolved)})
	}
	if !task.Due.IsZero() {
		rows = append(rows, []string{"Due", fmt.Sprint(task.Due)})
	}
	termWidth, _ := terminalSize()
	var styles []rowStyle
	for i := range rows {
		bg := 232
		if i%2 == 0 {
			bg = 233
		}
		styles = append(styles, rowStyle{fg: 250, bg: bg})
	}
	// header row is Name/Value, data rows alternate starting at 233
	fmt.Print(renderTable(table{
		header: []string{"Name", "Value"},
		rows:   rows,
		styles: styles,
	}, termWidth))
	printNotes(task)
}

func printJSON(v interface{}) {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		ExitError("%s", err.Error())
	}
	fmt.Print(string(data))
}

// ---- resolved report ----

func displayResolved(ts *TaskSet, tasks []*Task) {
	sortResolvedTasks(tasks)
	if !isRealTerminal() {
		printJSON(tasks)
		return
	}
	termWidth, _ := terminalSize()
	// group by ISO week
	type group struct {
		year, week int
		tasks      []*Task
	}
	var groups []*group
	for _, task := range tasks {
		y, w := task.Resolved.ISOWeek()
		if len(groups) == 0 || groups[len(groups)-1].year != y || groups[len(groups)-1].week != w {
			groups = append(groups, &group{year: y, week: w})
		}
		g := groups[len(groups)-1]
		g.tasks = append(g.tasks, task)
	}
	for _, g := range groups {
		first := g.tasks[0]
		fmt.Printf("\n\n> Week %d, starting %s\n\n", g.week, first.Resolved.Format("Mon 2 Jan 2006"))
		var rows [][]string
		var styles []rowStyle
		for i, task := range g.tasks {
			st := styleForTask(task, i)
			rows = append(rows, []string{
				task.Resolved.Format("Mon 2"),
				task.Priority,
				strings.Join(task.Tags, " "),
				dueString(task.Due),
				task.Project,
				summaryCell(task, st.fg),
			})
			styles = append(styles, st)
		}
		fmt.Print(renderTable(table{
			header: []string{"Resolved", "Priority", "Tags", "Due", "Project", "Summary"},
			rows:   rows,
			styles: styles,
		}, termWidth))
	}
	fmt.Printf("%d tasks.\n", len(tasks))
}

// ---- projects ----

type Project struct {
	Name          string    `json:"name"`
	TaskCount     int       `json:"taskCount"`
	ResolvedCount int       `json:"resolvedCount"`
	Active        bool      `json:"active"`
	Created       time.Time `json:"created"`
	Resolved      time.Time `json:"resolved"`
	Priority      string    `json:"priority"`
}

func buildProjects(tasks []*Task) []*Project {
	byName := map[string]*Project{}
	for _, task := range tasks {
		if task.Project == "" {
			continue
		}
		p, ok := byName[task.Project]
		if !ok {
			p = &Project{Name: task.Project, Priority: "P3"}
			byName[task.Project] = p
		}
		p.TaskCount++
		if task.Status == StatusResolved {
			p.ResolvedCount++
			if task.Resolved.After(p.Resolved) {
				p.Resolved = task.Resolved
			}
		}
		if task.Status == StatusActive {
			p.Active = true
		}
		if p.Created.IsZero() || task.Created.Before(p.Created) {
			p.Created = task.Created
		}
		if task.Status != StatusResolved {
			if task.Priority < p.Priority {
				p.Priority = task.Priority
			}
		}
	}
	names := make([]string, 0, len(byName))
	for name := range byName {
		names = append(names, name)
	}
	sort.Strings(names)
	out := []*Project{}
	for _, name := range names {
		out = append(out, byName[name])
	}
	return out
}

func displayProjects(projects []*Project) {
	if !IsInteractive() {
		printJSON(projects)
		return
	}
	termWidth, _ := terminalSize()
	var rows [][]string
	var styles []rowStyle
	idx := 0
	for _, p := range projects {
		if p.ResolvedCount >= p.TaskCount {
			continue
		}
		var st rowStyle
		if p.Active {
			st = rowStyle{fg: 233, bg: 250}
		} else {
			base := styleForTask(&Task{Priority: p.Priority}, idx)
			st = base
		}
		rows = append(rows, []string{
			p.Name,
			fmt.Sprintf("%d/%d", p.ResolvedCount, p.TaskCount),
			p.Created.Format("Mon 2 Jan 2006"),
		})
		styles = append(styles, st)
		idx++
	}
	fmt.Print(renderTable(table{
		header: []string{"Name", "Progress", "Created"},
		rows:   rows,
		styles: styles,
	}, termWidth))
}

