	ResolvedCount int       `json:"resolvedCount"`
	Active        bool      `json:"active"`
	Created       time.Time `json:"created"`
	Resolved      time.Time `json:"resolved"`
	Priority      string    `json:"priority"`
}

func buildProjects(tasks []*Task) []*Project {
	byName := map[string]*Project{}
	for _, task := range tasks {
		if task.Project == "" {
			continue
		}
		p, ok := byName[task.Project]
		if !ok {
			p = &Project{Name: task.Project, Priority: "P3"}
			byName[task.Project] = p
		}
		p.TaskCount++
		if task.Status == StatusResolved {
			p.ResolvedCount++
			if task.Resolved.After(p.Resolved) {
				p.Resolved = task.Resolved
			}
		}
		if task.Status == StatusActive {
			p.Active = true
		}
		if p.Created.IsZero() || task.Created.Before(p.Created) {
			p.Created = task.Created
		}
		if task.Status != StatusResolved {
			if task.Priority < p.Priority {
				p.Priority = task.Priority
			}
		}
	}
	names := make([]string, 0, len(byName))
	for name := range byName {
		names = append(names, name)
	}
	sort.Strings(names)
	out := []*Project{}
	for _, name := range names {
		out = append(out, byName[name])
	}
	return out
}

func displayProjects(projects []*Project) {
	if !IsInteractive() {
		printJSON(projects)
		return
	}
	termWidth, _ := terminalSize()
	var rows [][]string
	var styles []rowStyle
	idx := 0
	for _, p := range projects {
		if p.ResolvedCount >= p.TaskCount {
			continue
		}
		var st rowStyle
		if p.Active {
			st = rowStyle{fg: 233, bg: 250}
		} else {
			base := styleForTask(&Task{Priority: p.Priority}, idx)
			st = base
		}
		rows = append(rows, []string{
			p.Name,
			fmt.Sprintf("%d/%d", p.ResolvedCount, p.TaskCount),
			p.Created.Format("Mon 2 Jan 2006"),
		})
		styles = append(styles, st)
		idx++
	}
	fmt.Print(renderTable(table{
		header: []string{"Name", "Progress", "Created"},
		rows:   rows,
		styles: styles,
	}, termWidth))
}

