// ---- rune width handling ----

func runeDisplayWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 32 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	if isCombining(r) {
		return 0
	}
	if isWideRune(r) {
		return 2
	}
	return 1
}

func isCombining(r rune) bool {
	return (r >= 0x0300 && r <= 0x036f) || (r >= 0x1ab0 && r <= 0x1aff) ||
		(r >= 0x1dc0 && r <= 0x1dff) || (r >= 0x20d0 && r <= 0x20ff) ||
		(r >= 0xfe20 && r <= 0xfe2f) || (r >= 0xfe00 && r <= 0xfe0f)
}

func isWideRune(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115f,
		r >= 0x2e80 && r <= 0xa4cf,
		r >= 0xac00 && r <= 0xd7a3,
		r >= 0xf900 && r <= 0xfaff,
		r >= 0xfe30 && r <= 0xfe6f,
		r >= 0xff00 && r <= 0xff60,
		r >= 0xffe0 && r <= 0xffe6,
		r >= 0x20000 && r <= 0x3ffff,
		r >= 0x1f300 && r <= 0x1faff,
		r >= 0x2600 && r <= 0x27bf:
		return true
	}
	return false
}

// ansiSegments splits a string into text runs and ANSI escape sequences.
type ansiSeg struct {
	text    string
	isEsc   bool
}

func splitANSI(s string) []ansiSeg {
	var segs []ansiSeg
	for len(s) > 0 {
		i := strings.Index(s, "\x1b[")
		if i < 0 {
			segs = append(segs, ansiSeg{text: s})
			break
		}
		if i > 0 {
			segs = append(segs, ansiSeg{text: s[:i]})
			s = s[i:]
			continue
		}
		// escape sequence, find final byte (letter)
		j := 2
		for j < len(s) && !((s[j] >= 'a' && s[j] <= 'z') || (s[j] >= 'A' && s[j] <= 'Z')) {
			j++
		}
		if j < len(s) {
			j++
		}
		segs = append(segs, ansiSeg{text: s[:j], isEsc: true})
		s = s[j:]
	}
	return segs
}

func plainText(s string) string {
	var b strings.Builder
	for _, sg := range splitANSI(s) {
		if !sg.isEsc {
			b.WriteString(sg.text)
		}
	}
	return b.String()
}

// widthForMax mirrors the original: escape sequences each add one to the
// measured width of a cell.
func widthForMax(s string) int {
	segs := splitANSI(s)
	w := 0
	for _, sg := range segs {
		if sg.isEsc {
			w++
		} else {
			for _, r := range sg.text {
				w += runeDisplayWidth(r)
			}
		}
	}
	return w
}

func visibleWidth(s string) int {
	w := 0
	for _, sg := range splitANSI(s) {
		if sg.isEsc {
			continue
		}
		for _, r := range sg.text {
			w += runeDisplayWidth(r)
		}
	}
	return w
}

func truncateCell(s string, width int) string {
	if width < 0 {
		width = 0
	}
	if visibleWidth(s) <= width {
		return s
	}
	var b strings.Builder
	w := 0
	var trailingEsc []string
	segs := splitANSI(s)
	for i, sg := range segs {
		if sg.isEsc {
			// remember escapes after the cut point if they are at the end
			restAllEsc := true
			for _, rsg := range segs[i:] {
				if !rsg.isEsc {
					// check whether remaining text will be included
					_ = restAllEsc
				}
			}
			trailingEsc = append(trailingEsc, sg.text)
			continue
		}
		for _, r := range sg.text {
			rw := runeDisplayWidth(r)
			if w+rw > width {
				// emit trailing escapes collected so far
				for _, e := range trailingEsc {
					b.WriteString(e)
				}
				return b.String()
			}
			// flush pending escapes before this rune
			for _, e := range trailingEsc {
				b.WriteString(e)
			}
			trailingEsc = nil
			b.WriteRune(r)
			w += rw
		}
	}
	for _, e := range trailingEsc {
		b.WriteString(e)
	}
	return b.String()
}

func padCell(s string, width int) string {
	vw := visibleWidth(s)
	if vw >= width {
		return s
	}
	pad := strings.Repeat(" ", width-vw)
	segs := splitANSI(s)
	// if the cell ends with an escape sequence, insert padding before it
	if len(segs) > 0 && segs[len(segs)-1].isEsc {
		idx := strings.LastIndex(s, "\x1b[")
		if idx >= 0 {
			return s[:idx] + pad + s[idx:]
		}
	}
	return s + pad
}

type table struct {
	header []string
	rows   [][]string
	styles []rowStyle // per data row; nil meaning use default alternating
}

func renderTable(t table, termWidth int) string {
	cols := len(t.header)
	widths := make([]int, cols)
	for i, h := range t.header {
		widths[i] = widthForMax(h)
	}
	for _, row := range t.rows {
		for i := 0; i < cols && i < len(row); i++ {
			if w := widthForMax(row[i]); w > widths[i] {
				widths[i] = w
			}
		}
	}
	total := 0
	for _, w := range widths {
		total += w
	}
	if cols > 0 {
		total += (cols - 1) * 2
	}
	for total > termWidth {
		// decrement widest column (leftmost on ties)
		maxIdx := -1
		maxW := 1
		for i, w := range widths {
			if w > maxW {
				maxW = w
				maxIdx = i
			}
		}
		if maxIdx < 0 {
			break
		}
		widths[maxIdx]--
		total--
	}
	var b strings.Builder
	renderRow := func(cells []string, style string) {
		b.WriteString(style)
		for i := 0; i < cols; i++ {
			if i > 0 {
