		q := mergedQuery(query, cfg)
		displayTasks(ts, ts.FilterByStatuses(q, openStatuses), false)
	case "show-active":
		ts := LoadTaskSet(repo)
		q := mergedQuery(query, cfg)
		displayTasks(ts, ts.FilterByStatuses(q, map[string]bool{StatusActive: true}), true)
	case "show-paused":
		ts := LoadTaskSet(repo)
		q := mergedQuery(query, cfg)
		displayTasks(ts, ts.FilterByStatuses(q, map[string]bool{StatusPaused: true}), true)
	case "show-templates":
		ts := LoadTaskSet(repo)
		q := mergedQuery(query, cfg)
		displayTasks(ts, ts.FilterByStatuses(q, map[string]bool{StatusTemplate: true}), true)
