func commandCompletions(cfg *Config, args []string) {
	ts := LoadTaskSet(cfg.RepoPath)
	words := []string{}
	if len(args) > 1 {
		words = args[1:]
	}
	var given []string
	current := ""
	if len(words) == 1 {
		// just the program name
	} else if len(words) > 1 {
		current = words[len(words)-1]
		given = words[1 : len(words)-1]
	}
	givenQuery, err := ParseQuery(given)
	if err != nil {
		ExitError("%s", err.Error())
	}

	// attribute candidates
	var attrs []string
	attrs = append(attrs, "P0", "P1", "P2", "P3")
	projectSet := map[string]bool{}
	for _, t := range ts.Tasks {
		if t.Status != StatusResolved && t.Project != "" {
			projectSet[t.Project] = true
		}
	}
	var projectNames []string
	for name := range projectSet {
		projectNames = append(projectNames, name)
	}
	sortStrings(projectNames)
	for _, name := range projectNames {
		attrs = append(attrs, "project:"+name, "-project:"+name)
	}
	contextTasks := ts.FilterByStatuses(cfg.State.Context, openStatuses)
	tagSet := map[string]bool{}
	for _, t := range contextTasks {
		for _, tag := range t.Tags {
			tagSet[tag] = true
		}
	}
	for tag := range tagSet {
		attrs = append(attrs, "+"+tag, "-"+tag)
	}

	var candidates []string
	if givenQuery.Cmd == "help" {
		candidates = append(candidates, completionCommands...)
	} else if givenQuery.Cmd != "" {
		if completionQueryCommands[givenQuery.Cmd] {
			candidates = append(candidates, attrs...)
		} else {
			candidates = []string{}
		}
	} else {
		if givenQuery.hasOperators() {
			candidates = append(candidates, attrs...)
		} else {
			candidates = append(candidates, completionCommands...)
			candidates = append(candidates, attrs...)
		}
	}

	for _, cand := range candidates {
		if cand == current {
			continue
		}
		already := false
		for _, g := range given {
			if g == cand {
				already = true
				break
			}
		}
		if already {
			continue
		}
		if strings.HasPrefix(cand, current) {
			fmt.Println(cand)
		}
	}
	_ = time.Now
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}
