func printHelp(args []string) {
	topic := ""
	if len(args) >= 2 {
		topic = args[1]
	}
	if canonical, ok := helpAliases[topic]; ok {
		topic = canonical
	}
	if topic == "bash-completion" || topic == "fish-completion" || topic == "zsh-completion" {
		fmt.Fprint(os.Stderr, completionHelp)
		return
	}
	if text, ok := helpTopics[topic]; ok {
		fmt.Fprint(os.Stderr, text)
		return
	}
	fmt.Fprint(os.Stderr, genericHelp)
}

func mergedQuery(query Query, cfg *Config) Query {
	q := query
	if !q.IgnoreContext {
		if err := q.Apply(cfg.State.Context); err != nil {
			ExitError("%s", err.Error())
		}
	}
	return q
}

func printContextWarning(cfg *Config) {
	ctxStr := cfg.State.Context.String()
	if ctxStr == "" {
		return
	}
	if cfg.ContextFromEnv {
		fmt.Printf("\x1b[33mActive context (set by DSTASK_CONTEXT): %s\x1b[0m\n", ctxStr)
	} else {
		fmt.Printf("\x1b[33mActive context: %s\x1b[0m\n", ctxStr)
	}
}

func newTaskFromQuery(q Query, status string) *Task {
	task := &Task{
		Uuid:         newUUID(),
		Status:       status,
		Summary:      q.Text,
		Notes:        q.Note,
		Tags:         append([]string{}, q.Tags...),
		Project:      q.Project,
		Priority:     q.Priority,
		Due:          q.Due,
		Subtasks:     []SubTask{},
		Dependencies: []string{},
		Created:      nowUTC(),
	}
	if task.Priority == "" {
		task.Priority = "P2"
	}
	task.Normalise()
	return task
}

func commandAdd(cfg *Config, query Query) {
	if query.Text == "" && query.Template == 0 {
		ExitError("task description or template required")
	}
	ts := LoadTaskSet(cfg.RepoPath)
	if query.Template != 0 {
		src := ts.GetOpenTask(query.Template)
		merged := mergedQuery(query, cfg)
		task := &Task{
			Uuid:         newUUID(),
			Status:       StatusPending,
			Summary:      src.Summary,
			Notes:        src.Notes,
			Tags:         append([]string{}, src.Tags...),
			Project:      src.Project,
			Priority:     src.Priority,
			Due:          src.Due,
			Subtasks:     []SubTask{},
			Dependencies: []string{},
			Created:      nowUTC(),
		}
		if merged.Text != "" {
			task.Summary = merged.Text
		}
		ApplyQuery(task, merged)
		ts.AddTask(task)
		msg := "Added " + task.String()
		ts.SaveTask(task, msg)
		if src.Status != StatusTemplate {
			fmt.Printf("\nYou've copied an open task!\nTo learn more about creating templates enter 'dstask help template'\n\n")
		}
		return
	}
	printContextWarning(cfg)
	merged := mergedQuery(query, cfg)
	task := newTaskFromQuery(merged, StatusPending)
	ts.AddTask(task)
	msg := "Added " + task.String()
	ts.SaveTask(task, msg)
}

func commandLog(cfg *Config, query Query) {
	if query.Text == "" {
		ExitError("task description required")
	}
	ts := LoadTaskSet(cfg.RepoPath)
	printContextWarning(cfg)
	merged := mergedQuery(query, cfg)
	task := newTaskFromQuery(merged, StatusResolved)
	task.Resolved = nowUTC()
	task.Created = nowUTC()
	ts.AddTask(task)
	msg := "Logged " + task.Summary
	ts.SaveTask(task, msg)
}

func commandTemplate(cfg *Config, query Query) {
	ts := LoadTaskSet(cfg.RepoPath)
	if len(query.IDs) > 0 {
		snap := ts.snapshotOpenTasks()
		for _, id := range query.IDs {
			task := ts.getFromSnapshot(snap, id)
			if err := task.ChangeStatus(StatusTemplate); err != nil {
				ExitError("%s", err.Error())
			}
			msg := fmt.Sprintf("Changed %s to Template", task.String())
			ts.SaveTask(task, msg)
		}
		return
	}
	if query.Text != "" {
		merged := mergedQuery(query, cfg)
		task := newTaskFromQuery(merged, StatusTemplate)
		ts.AddTask(task)
		msg := "Created Template " + task.String()
		ts.SaveTask(task, msg)
	}
}

func commandStart(cfg *Config, query Query) {
	ts := LoadTaskSet(cfg.RepoPath)
	if query.Template != 0 {
		ExitError("templates not yet supported for start command")
	}
	if len(query.IDs) > 0 {
		snap := ts.snapshotOpenTasks()
		for _, id := range query.IDs {
			task := ts.getFromSnapshot(snap, id)
			if query.Text != "" {
				task.Notes += "\n" + query.Text
			}
			if err := task.ChangeStatus(StatusActive); err != nil {
				ExitError("%s", err.Error())
			}
			msg := "Started " + task.String()
			ts.SaveTask(task, msg)
			printNotes(task)
		}
		return
	}
	if query.Text != "" {
		merged := mergedQuery(query, cfg)
		task := newTaskFromQuery(merged, StatusActive)
		ts.AddTask(task)
		msg := "Added and started " + task.String()
		ts.SaveTask(task, msg)
		return
	}
	ExitError("nothing to do -- specify an ID or describe a task")
}

// commandStop handles both stop (isStop=true) and done/resolve.
func commandStop(cfg *Config, query Query, isStop bool) {
	var ts *TaskSet
	if isStop {
		ts = LoadTaskSet(cfg.RepoPath)
		if query.hasOperators() {
			ExitError("operators not valid in this context")
		}
		if len(query.IDs) == 0 {
			ExitError("no ID(s) specified")
		}
	} else {
		if query.hasOperators() {
			ExitError("operators not valid in this context")
		}
		if len(query.IDs) == 0 {
			ExitError("no ID(s) specified")
		}
		ts = LoadTaskSet(cfg.RepoPath)
	}
	snap := ts.snapshotOpenTasks()
	for _, id := range query.IDs {
		task := ts.getFromSnapshot(snap, id)
		if query.Text != "" {
			task.Notes += "\n" + query.Text
		}
		var msg string
		if isStop {
			if err := task.ChangeStatus(StatusPaused); err != nil {
				ExitError("%s", err.Error())
			}
			msg = "Stopped " + task.String()
		} else {
			if err := task.ChangeStatus(StatusResolved); err != nil {
				ExitError("%s", err.Error())
			}
			msg = "Resolved " + task.String()
		}
		ts.SaveTask(task, msg)
	}
}

func commandRemove(cfg *Config, query Query) {
	if len(query.IDs) == 0 {
		ExitError("no ID(s) specified")
	}
	if query.hasOperators() {
		ExitError("operators not valid in this context")
	}
	ts := LoadTaskSet(cfg.RepoPath)
	snap := ts.snapshotOpenTasks()
	var tasks []*Task
	for _, id := range query.IDs {
		task := ts.getFromSnapshot(snap, id)
		fmt.Printf("%d: %s\n", task.ID, task.Summary)
		tasks = append(tasks, task)
	}
	for _, task := range tasks {
		path := filepath.Join(cfg.RepoPath, task.Status, task.Uuid+".yml")
		if err := os.Remove(path); err != nil {
			ExitError("Could not remove task %s: %s", path, err.Error())
		}
		msg := "Removed: " + task.String()
		if query.Text != "" {
			msg += "\n\n" + query.Text
		}
		fmt.Printf("\n%s\n", msg)
		gitCommit(cfg.RepoPath, msg)
	}
}

func commandModify(cfg *Config, query Query) {
	if !query.hasOperators() {
		ExitError("no operations specified")
	}
	ts := LoadTaskSet(cfg.RepoPath)
	if len(query.IDs) > 0 {
		snap := ts.snapshotOpenTasks()
		for _, id := range query.IDs {
			task := ts.getFromSnapshot(snap, id)
			ApplyQuery(task, query)
			msg := "Modified " + task.String()
			ts.SaveTask(task, msg)
		}
		return
	}
	filtered := ts.FilterByStatuses(cfg.State.Context, openStatuses)
	if IsInteractive() {
		ConfirmOrAbort(fmt.Sprintf("no IDs specified. Apply to all %d tasks in current ctx?", len(filtered)))
	}
	byID := map[int]*Task{}
	for _, t := range filtered {
		byID[t.ID] = t
	}
	for _, task := range byID {
		ApplyQuery(task, query)
		msg := "Modified " + task.String()
		ts.SaveTask(task, msg)
	}
}

func editText(initial string, task *Task, ext string) string {
	f, err := os.CreateTemp("", fmt.Sprintf("dstask.*.%d-%s.%s", task.ID, slugify(task.Summary), ext))
	if err != nil {
		ExitError("Could not create temporary file to edit")
	}
	defer os.Remove(f.Name())
	if _, err := f.WriteString(initial); err != nil {
		ExitError("Could not create temporary file to edit")
	}
	f.Close()
	editor := os.Getenv("EDITOR")
	parts := strings.Fields(editor)
	if len(parts) == 0 {
		ExitError("Failed to run $EDITOR")
	}
	cmd := exec.Command(parts[0], append(parts[1:], f.Name())...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		ExitError("Failed to run $EDITOR")
	}
	data, err := os.ReadFile(f.Name())
	if err != nil {
		ExitError("Could not read back temporary edited file")
	}
	return string(data)
}

func commandNote(cfg *Config, query Query) {
	if len(query.IDs) == 0 {
		ExitError("no ID(s) specified")
	}
	if query.hasOperators() {
		ExitError("operators not valid in this context")
	}
	ts := LoadTaskSet(cfg.RepoPath)
	snap := ts.snapshotOpenTasks()
	for _, id := range query.IDs {
		task := ts.getFromSnapshot(snap, id)
		if !IsInteractive() {
			fmt.Print(task.Notes)
			continue
		}
		if query.Text != "" {
			if task.Notes != "" {
				task.Notes += "\n"
			}
			task.Notes += query.Text
		} else {
			task.Notes = editText(task.Notes, task, "md")
		}
		msg := fmt.Sprintf("Edit note %d: %s", task.ID, task.Summary)
		ts.SaveTask(task, msg)
	}
}

func commandEdit(cfg *Config, query Query) {
	if query.hasOperators() {
		ExitError("operators not valid in this context")
	}
	if len(query.IDs) == 0 {
		ExitError("no ID(s) specified")
	}
	ts := LoadTaskSet(cfg.RepoPath)
	snap := ts.snapshotOpenTasks()
	for _, id := range query.IDs {
		task := ts.getFromSnapshot(snap, id)
		var edited *Task
		for {
			data, err := yaml.Marshal(task)
			if err != nil {
				ExitError("%s", err.Error())
			}
			text := editText(string(data), task, "yml")
			candidate := *task
			if err := yaml.Unmarshal([]byte(text), &candidate); err != nil {
				fmt.Fprintf(os.Stderr, "Failed to unmarshal yaml: %s\n", err.Error())
				ConfirmOrAbort("Try again?")
				continue
			}
			edited = &candidate
			break
		}
		if err := checkTransition(task.Status, edited.Status); err != nil {
			ExitError("%s", err.Error())
		}
		uuid := task.Uuid
		taskID := task.ID
		origStatus := task.origStatus
		*task = *edited
		task.Uuid = uuid
		task.ID = taskID
		task.origStatus = origStatus
		msg := fmt.Sprintf("Edited %d: %s", task.ID, task.Summary)
		ts.SaveTask(task, msg)
	}
}

var urlCandidateRe = regexp.MustCompile(`(?i)(?:https?://|ftp://|www\.)[^\s<>"']+|[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}[^\s<>"']*|(?:[A-Za-z0-9\-]+\.)+(?:com|org|net|edu|gov|mil|int|io|ai|app|dev|co|me|info|biz|xyz|online|site|tech|blog|news|shop|store|travel|museum|name|pro|aero|asia|coop|mobi|jobs|travel|xxx|post|geo|[a-z]{2})(?:/[^\s<>"']*)?`)

func extractURLs(text string) []string {
	var urls []string
	for _, m := range urlCandidateRe.FindAllString(text, -1) {
		u := cleanURLCandidate(m)
		if u != "" {
			urls = append(urls, u)
		}
	}
	return urls
}

func cleanURLCandidate(u string) string {
	for len(u) > 0 {
		last := u[len(u)-1]
		if strings.ContainsRune(".,;:!?", rune(last)) {
			u = u[:len(u)-1]
			continue
		}
		if last == ')' && strings.Count(u, "(") < strings.Count(u, ")") {
			u = u[:len(u)-1]
			continue
		}
		if last == ']' && strings.Count(u, "[") < strings.Count(u, "]") {
			u = u[:len(u)-1]
			continue
		}
		if last == '}' && strings.Count(u, "{") < strings.Count(u, "}") {
			u = u[:len(u)-1]
			continue
		}
		if last == '"' || last == '\'' {
			u = u[:len(u)-1]
			continue
		}
		break
	}
	lower := strings.ToLower(u)
	if lower == "http://" || lower == "https://" || lower == "ftp://" || lower == "www." {
		return ""
	}
	if strings.HasPrefix(lower, "http://") || strings.HasPrefix(lower, "https://") || strings.HasPrefix(lower, "ftp://") {
		rest := u[strings.Index(lower, "://")+3:]
		if rest == "" || strings.HasPrefix(rest, ".") {
			return ""
		}
	}
	return u
}

func openBrowser(url string) {
	cmd := exec.Command("xdg-open", url)
	if err := cmd.Start(); err != nil {
		ExitError("Failed to open browser")
	}
}

func commandOpen(cfg *Config, query Query) {
	if len(query.IDs) == 0 {
		ExitError("no ID(s) specified")
	}
	if query.hasOperators() {
		ExitError("operators not valid in this context")
	}
	ts := LoadTaskSet(cfg.RepoPath)
	snap := ts.snapshotOpenTasks()
	for _, id := range query.IDs {
		task := ts.getFromSnapshot(snap, id)
		urls := extractURLs(task.Summary)
		urls = append(urls, extractURLs(task.Notes)...)
		if len(urls) == 0 {
			ExitError("no URLs found in task %d", id)
		}
		for _, u := range urls {
			openBrowser(u)
		}
	}
}

func commandContext(cfg *Config, query Query, args []string) {
	if len(args) == 1 {
		fmt.Println(cfg.State.Context.String())
		if !cfg.ContextFromEnv {
			cfg.SaveState()
		}
		return
	}
	if cfg.ContextFromEnv {
		ExitError("setting context not allowed while DSTASK_CONTEXT is set")
	}
	if len(args) >= 2 && args[1] == "none" {
		cfg.State.Context = Query{}
		cfg.SaveState()
		return
	}
	if len(query.IDs) > 0 {
		ExitError("context cannot contain IDs")
	}
	if query.Text != "" {
		ExitError("context cannot contain text")
	}
	cfg.State.Context = query
	cfg.SaveState()
}

func commandUndo(cfg *Config, args []string) {
	raw := []string{}
	if len(args) > 1 {
		raw = args[1:]
	}
	n := 1
	if len(raw) == 1 {
		parsed, err := strconv.Atoi(raw[0])
		if err != nil {
			fmt.Fprint(os.Stderr, helpTopics["undo"])
			return
		}
		n = parsed
	}
	runGitPassthrough(cfg.RepoPath, "revert", "--no-edit", fmt.Sprintf("HEAD~%d..", n))
}

var completionCommands = []string{
	"next", "add", "rm", "remove", "template", "log", "start", "note", "notes", "stop", "done", "resolve",
	"context", "modify", "edit", "undo", "sync", "open", "git", "show-next", "show-projects", "show-tags",
	"show-active", "show-paused", "show-open", "show-resolved", "show-templates", "show-unorganised",
	"bash-completion", "fish-completion", "zsh-completion", "help", "version",
}

var completionQueryCommands = map[string]bool{
	"next": true, "add": true, "remove": true, "log": true, "start": true, "stop": true, "done": true,
	"resolve": true, "context": true, "modify": true, "show-next": true, "show-projects": true,
	"show-active": true, "show-paused": true, "show-open": true, "show-resolved": true, "show-templates": true,
}

func commandCompletions(cfg *Config, args []string) {
	ts := LoadTaskSet(cfg.RepoPath)
	words := []string{}
	if len(args) > 1 {
		words = args[1:]
	}
	var given []string
	current := ""
	if len(words) == 1 {
		// just the program name
	} else if len(words) > 1 {
		current = words[len(words)-1]
		given = words[1 : len(words)-1]
	}
	givenQuery, err := ParseQuery(given)
	if err != nil {
		ExitError("%s", err.Error())
	}

	// attribute candidates
	var attrs []string
	attrs = append(attrs, "P0", "P1", "P2", "P3")
	projectSet := map[string]bool{}
	for _, t := range ts.Tasks {
		if t.Status != StatusResolved && t.Project != "" {
			projectSet[t.Project] = true
		}
	}
	var projectNames []string
	for name := range projectSet {
		projectNames = append(projectNames, name)
	}
	sortStrings(projectNames)
	for _, name := range projectNames {
		attrs = append(attrs, "project:"+name, "-project:"+name)
	}
	contextTasks := ts.FilterByStatuses(cfg.State.Context, openStatuses)
	tagSet := map[string]bool{}
	for _, t := range contextTasks {
		for _, tag := range t.Tags {
			tagSet[tag] = true
		}
	}
	for tag := range tagSet {
		attrs = append(attrs, "+"+tag, "-"+tag)
	}

	var candidates []string
	if givenQuery.Cmd == "help" {
		candidates = append(candidates, completionCommands...)
	} else if givenQuery.Cmd != "" {
		if completionQueryCommands[givenQuery.Cmd] {
			candidates = append(candidates, attrs...)
		} else {
			candidates = []string{}
		}
	} else {
		if givenQuery.hasOperators() {
			candidates = append(candidates, attrs...)
		} else {
			candidates = append(candidates, completionCommands...)
			candidates = append(candidates, attrs...)
		}
	}

	for _, cand := range candidates {
		if cand == current {
			continue
		}
		already := false
		for _, g := range given {
			if g == cand {
				already = true
				break
			}
		}
		if already {
			continue
		}
		if strings.HasPrefix(cand, current) {
			fmt.Println(cand)
		}
	}
	_ = time.Now
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}
