{"command":"cat > dstask/yamlencode.go <<'EOF'
package dstask

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
)

var yamlNumberLike = regexp.MustCompile(`^[-+]?[0-9]+$|^[-+]?([0-9][0-9_]*)?\.[0-9_]*([eE][-+]?[0-9]+)?$|^[-+]?[0-9][0-9_]*(:[0-5]?[0-9])+(\.[0-9]*)?$|^0b[0-1_]+$|^0[0-7_]+$|^0x[0-9a-fA-F_]+$`)
var yamlTimestampLike = regexp.MustCompile(`^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]([Tt ]|[0-9][0-9]:).*`)

func looksNonString(s string) bool {
	lower := strings.ToLower(s)
	switch lower {
	case "y", "yes", "n", "no", "true", "false", "on", "off", "null", "~", ".inf", "-.inf", "+.inf", ".nan":
		return true
	}
	if yamlNumberLike.MatchString(s) {
		return true
	}
	if yamlTimestampLike.MatchString(s) {
		return true
	}
	return false
}

func isPlainSafe(s string) bool {
	if s == "" {
		return false
	}
	if strings.TrimSpace(s) != s {
		return false
	}
	// cannot start with an indicator
	first := s[0]
	if strings.ContainsRune("-?:,[]{}#&*!|>'\"%@`", rune(first)) {
		// '-' '?' ':' are safe when not followed by space in some cases,
		// but the original (yaml.v2) quotes the observed leading forms;
		// a leading '-' followed by a non-space is plain in a few cases,
		// handled by callers through tags starting with '-'. To match the
		// observed summaries, quote all of these.
		return false
	}
	if strings.Contains(s, ": ") || strings.Contains(s, " #") || strings.HasSuffix(s, ":") {
		return false
	}
	return true
}

func encodeStringScalar(s string) string {
	if s == "" {
		return `""`
	}
	if strings.Contains(s, "\n") {
		if enc, ok := encodeLiteral(s, 0); ok {
			return enc
		}
		return strconv.Quote(s)
	}
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return strconv.Quote(s)
		}
	}
	if looksNonString(s) {
		return strconv.Quote(s)
	}
	if isPlainSafe(s) {
		return s
	}
	// single-quoted style, doubling single quotes
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

// encodeLiteral returns a literal block scalar at the given base indent
// (number of spaces of the enclosing mapping key). The returned string
// starts with the block header (|...) and includes trailing newline.
func encodeLiteral(s string, baseIndent int) (string, bool) {
	for _, r := range s {
		if (r < 0x20 && r != '\n') || r == 0x7f {
			return "", false
		}
	}
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		if strings.HasSuffix(line, " ") || strings.HasSuffix(line, "\t") {
			return "", false
		}
	}
	header := "|"
	needIndent := strings.HasPrefix(s, "\n") || strings.HasPrefix(s, " ")
	chomp := ""
	trailing := 0
	for i := len(s) - 1; i >= 0 && s[i] == '\n'; i-- {
		trailing++
	}
	if trailing == 0 {
		chomp = "-"
	} else if trailing > 1 {
		chomp = "+"
	}
	if needIndent {
		header = "|2" + chomp
	} else {
		header = "|" + chomp
	}
	contentLines := lines
	if trailing > 0 {
		contentLines = lines[:len(lines)-1]
	}
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("\n")
	pad := strings.Repeat(" ", baseIndent+2)
	for _, line := range contentLines {
		if line == "" {
			b.WriteString("\n")
		} else {
			b.WriteString(pad)
			b.WriteString(line)
			b.WriteString("\n")
		}
	}
	if trailing > 1 {
		for i := 1; i < trailing; i++ {
			b.WriteString("\n")
		}
	}
	return b.String(), true
}

func encodeStringField(key string, s string, indent int) string {
	pad := strings.Repeat(" ", indent)
	if strings.Contains(s, "\n") {
		if enc, ok := encodeLiteral(s, indent); ok {
			return pad + key + ": " + enc
		}
	}
	return pad + key + ": " + encodeStringScalar(s) + "\n"
}

func formatYAMLTime(t time.Time) string {
	return t.Format("2006-01-02T15:04:05.999999999Z07:00")
}

func marshalTaskForEdit(task *Task) []byte {
	var b strings.Builder
	b.WriteString(encodeStringField("status", task.Status, 0))
	b.WriteString(marshalTaskFields(task))
	return []byte(b.String())
}

func marshalTaskForFile(task *Task) []byte {
	return []byte(marshalTaskFields(task))
}

func marshalTaskFields(task *Task) string {
	var b strings.Builder
	b.WriteString(encodeStringField("summary", task.Summary, 0))
	b.WriteString(encodeStringField("notes", task.Notes, 0))
	// tags
	if len(task.Tags) == 0 {
		b.WriteString("tags: []\n")
	} else {
		b.WriteString("tags:\n")
		for _, tag := range task.Tags {
			b.WriteString("- " + encodeStringScalar(tag) + "\n")
		}
	}
	b.WriteString(encodeStringField("project", task.Project, 0))
	b.WriteString(encodeStringField("priority", task.Priority, 0))
	b.WriteString(encodeStringField("delegatedto", task.DelegatedTo, 0))
	if len(task.Subtasks) == 0 {
		b.WriteString("subtasks: []\n")
	} else {
		b.WriteString("subtasks:\n")
		for _, st := range task.Subtasks {
			b.WriteString("- " + strings.TrimPrefix(encodeStringField("summary", st.Summary, 2), "  "))
			b.WriteString(fmt.Sprintf("  resolved: %v\n", st.Resolved))
		}
	}
	if len(task.Dependencies) == 0 {
		b.WriteString("dependencies: []\n")
	} else {
		b.WriteString("dependencies:\n")
		for _, dep := range task.Dependencies {
			b.WriteString("- " + encodeStringScalar(dep) + "\n")
		}
	}
	b.WriteString("created: " + formatYAMLTime(task.Created) + "\n")
	b.WriteString("resolved: " + formatYAMLTime(task.Resolved) + "\n")
	b.WriteString("due: " + formatYAMLTime(task.Due) + "\n")
	return b.String()
}
EOF
